import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CFuv5BrO.js";const m=JSON.parse('{"title":"Stage 2 · Personal Operator","description":"Hearth Stage 2 development module: read-only connectors, document and data execution, web research, draft approvals, Context Compiler, Token Governor, and Memory v0.","frontmatter":{"title":"Stage 2 · Personal Operator","description":"Hearth Stage 2 development module: read-only connectors, document and data execution, web research, draft approvals, Context Compiler, Token Governor, and Memory v0.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-2.md","filePath":"en/delivery/stage-2.md","lastUpdated":1793752688000}'),n={name:"en/delivery/stage-2.md"};function s(i,e,d,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<p class="eyebrow">MODULE 2 / 7</p><h1 id="stage-2-·-personal-operator" tabindex="-1">Stage 2 · Personal Operator <a class="header-anchor" href="#stage-2-·-personal-operator" aria-label="Permalink to &quot;Stage 2 · Personal Operator&quot;">​</a></h1><p class="lead">Expand from file tasks to most everyday content work. The order is read-only first, deterministic processing second, the browser third, and real writes on test accounts last.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Stage 1&#39;s durable tasks, approvals, idempotency, receipts, and recovery are stable.</li><li>The first connectors and document/data tasks are chosen, with test accounts available.</li><li>Every external source enters a unified Source model with permissions, provenance, and audit data.</li></ul><h2 id="development-steps" tabindex="-1">Development Steps <a class="header-anchor" href="#development-steps" aria-label="Permalink to &quot;Development Steps&quot;">​</a></h2><ol><li><strong>Connect read-only sources.</strong> Sync email, calendar, files, and knowledge bases read-only; add source views, deduplication, incremental sync, and permission checks.</li><li><strong>Add the Document/Data Executor.</strong> Support document conversion, tables, structured extraction, citation location, and verifiable artifacts.</li><li><strong>Add the Browser Executor.</strong> Start with public web research, citations, and page diffs; isolate sessions and defend against untrusted pages and prompt injection.</li><li><strong>Close test-account side effects.</strong> Use a test account to complete &quot;read → understand → draft → approve → send/write → receipt,&quot; verifying idempotency, reconciliation, and undo.</li><li><strong>Compile context and control cost.</strong> Add Context Compiler, Token Governor v1, and Memory v0; record recalled sources, Token use, and manual minutes.</li><li><strong>Complete the Stage 2 release.</strong> Evaluate representative daily tasks for success, manual minutes, cross-account isolation, failure recovery, and user trust.</li></ol><h2 id="increment-breakdown" tabindex="-1">Increment Breakdown <a class="header-anchor" href="#increment-breakdown" aria-label="Permalink to &quot;Increment Breakdown&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Increment</th><th>User-visible outcome</th><th>Completion evidence</th></tr></thead><tbody><tr><td>D2.1 Read-only connectors and source views</td><td>Users can inspect email, calendar, file, and knowledge sources</td><td>Sync, dedupe, incremental updates, permissions, source audit</td></tr><tr><td>D2.2 Document/Data Executor</td><td>Documents and tables convert, extract, and verify</td><td>Artifacts, citations, structure, and failure samples</td></tr><tr><td>D2.3 Browser Executor and web research</td><td>Research has sources, citations, and page-change evidence</td><td>Isolated sessions, page diffs, injection defenses</td></tr><tr><td>D2.4 Draft, approval, and test-account effects</td><td>Users approve sends/writes and inspect receipts</td><td>Test-account loop, idempotency, reconciliation, undo</td></tr><tr><td>D2.5 Context Compiler and Memory v0</td><td>Tasks use less context and explain recall</td><td>Token baseline, recall sources, budgets, degradation</td></tr><tr><td>D2.6 Stage 2 release</td><td>Manual minutes fall materially on daily content tasks</td><td>Real-task evaluation, cross-account isolation, security report</td></tr></tbody></table><h2 id="exit-checklist" tabindex="-1">Exit Checklist <a class="header-anchor" href="#exit-checklist" aria-label="Permalink to &quot;Exit Checklist&quot;">​</a></h2><ul><li>[ ] The email loop &quot;read → understand → draft → approve → send → receipt&quot; works.</li><li>[ ] Calendar conflict checks and approval-gated writes work.</li><li>[ ] Document conversion, data extraction, and web research are verifiable and traceable.</li><li>[ ] Manual minutes fall materially on common tasks, with a Token baseline.</li><li>[ ] No cross-account or cross-project data leakage; failures recover or explicitly move to human handling.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Taking over an unisolated primary account.</li><li>Sacrificing permissions, idempotency, and receipts for connector count.</li><li>Letting untrusted web content alter system permissions or approval policy.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Continue to <a href="/hearth-os/en/delivery/stage-3.html">Stage 3 · Computer Operator</a> for desktop software without APIs.</p>',15)])])}const h=t(n,[["render",s]]);export{m as __pageData,h as default};
